export type MeldingItem = {
  /** Стабільний ідентифікатор події. Stabiele id van de gebeurtenis. */
  id: string;
  kanaal: MeldingKanaal;
  /** bel/telegram/email: вид (kind) із shared/melding-soorten.ts; toast: джерело (source); activiteit: дія (owner.*); extensie: extensie.<ключ>. */
  soort: string;
  /** Підвид для backend/beveiliging-meldingen.ts (BeveiligingsWijziging). */
  sub?: string;
  /** Файл, де сповіщення створюється. Bestand waar de melding ontstaat. */
  bestand: string;
  type: MeldingType;
  niveau: MeldingNiveau;
  schema: MeldingSchemaId;
  titel: Tekst;
};

