/** Вид описано в shared/melding-soorten.ts, але жоден сервіс його ще не надсилає (запас на майбутнє). Soort bestaat, nog geen afzender. */
export const MELDING_SOORTEN_IN_RESERVE: readonly string[] = ['uitrol_voorstel', 'release', 'server', 'deur', 'siem'];

export const meldingVanId = (id: string): MeldingItem | undefined => MELDINGEN.find((m) => m.id === id);
export const meldingenVanSchema = (s: MeldingSchemaId): MeldingItem[] => MELDINGEN.filter((m) => m.schema === s);
export const meldingenVanKanaal = (k: MeldingKanaal): MeldingItem[] => MELDINGEN.filter((m) => m.kanaal === k);
/** Рівень події за видом і файлом (перше збігання); невідоме — звичайне. */
export const niveauVan = (kanaal: MeldingKanaal, soort: string, bestand?: string): MeldingNiveau =>
  MELDINGEN.find((m) => m.kanaal === kanaal && m.soort === soort && (!bestand || m.bestand === bestand))?.niveau ?? 'gewoon';
